"""The EPT matrix-method kernel matrices from the tables generated by ``tools/pt_autogen``
(``tables/ept_matrix.npz``).

A P22 block is ``R(nu1, nu2) I(nu1, nu2)`` and a P13 block ``R(nu1) tan(pi nu1) / pi``.  ``R``
is stored as a constant times a product of integer polynomial factors (positive powers in
the numerator, negative in the denominator), evaluated with numpy by Horner's rule.  Block names and the
conventions are stated in ``tools/pt_autogen/ept_matrix.py``.
"""
import os
from functools import lru_cache

import numpy as np
from scipy.special import loggamma

TABLE_FILE = os.path.join(os.path.dirname(__file__), 'tables', 'ept_matrix.npz')


def get_I(nu1, nu2):
    log_i = (
        -np.log(8 * np.pi**(3/2))
        + loggamma(3/2 - nu1)
        + loggamma(3/2 - nu2)
        + loggamma(nu1 + nu2 - 3/2)
        - loggamma(nu1)
        - loggamma(nu2)
        - loggamma(3 - nu1 - nu2)
    )
    return np.exp(log_i)


def _horner(coeffs, nu1, nu2=None):
    """``sum_i nu1^i sum_j coeffs[i, j] nu2^j`` (``sum_i coeffs[i] nu1^i`` for 1-d ``coeffs``):
    Horner's rule in nu1, then in nu2."""
    out = 0.0
    for row in coeffs[::-1]:
        if coeffs.ndim == 1:
            inner = row
        else:
            inner = 0.0
            for c in row[::-1]:
                inner = inner * nu2 + c
        out = out * nu1 + inner
    return out


def _trim(coeffs):
    """A coefficient array without its zero padding (trailing zero rows/columns)."""
    nonzero = np.nonzero(coeffs)
    return coeffs[tuple(slice(0, int(ix.max()) + 1) for ix in nonzero)]


@lru_cache(maxsize=None)
def _tables():
    """``{'22' | '13': (names, blocks, factors), 'uv': array}``.

    ``blocks[i] = (const, [(factor index, power)])``; ``factors`` are the distinct polynomial
    factors (trimmed coefficient arrays).
    """
    with np.load(TABLE_FILE, allow_pickle=False) as data:
        d = {key: data[key] for key in data.files}
    out = {'uv': d['uv']}
    for prefix in ('22', '13'):
        names = tuple(str(name) for name in d['names_' + prefix])
        blocks = [(float(c), []) for c in d['const_' + prefix]]
        index, factors = {}, []
        for coeffs, block, power in zip(d['factors_' + prefix], d['factor_block_' + prefix],
                                        d['factor_power_' + prefix]):
            key = coeffs.tobytes()
            if key not in index:
                index[key] = len(factors)
                factors.append(_trim(coeffs))
            blocks[int(block)][1].append((index[key], int(power)))
        out[prefix] = (names, blocks, factors)
    return out


def block_names(prefix):
    """Names of the blocks ``prefix`` ('22' or '13'), sorted as strings."""
    return list(_tables()[prefix][0])


def evaluate(prefix, names, *nu):
    """Kernel matrices of the blocks ``names`` at the numpy arrays ``nu``.

    ``prefix`` '22': ``R(nu1, nu2) I(nu1, nu2)`` at ``nu = (nu1, nu2)``; '13':
    ``R(nu1) tan(pi nu1) / pi`` at ``nu = (nu1,)``.  Each distinct factor and the outer
    function are evaluated once.
    """
    all_names, blocks, factors = _tables()[prefix]
    outer = get_I(*nu) if prefix == '22' else np.tan(np.pi * nu[0]) / np.pi
    values = {}
    out = []
    for name in names:
        const, flist = blocks[all_names.index(name)]
        num, den = const, 1.0
        for j, power in flist:
            if j not in values:
                values[j] = _horner(factors[j], *nu)
            for _ in range(abs(power)):
                if power > 0:
                    num = num * values[j]
                else:
                    den = den * values[j]
        out.append(num / den * outer)
    return out


def uv_table():
    """``(nterms, 7)`` monomials of ``Z1 Z3_UV``: powers of (mu, f, b1, b2, bG2, bGamma3) and the
    coefficient, sorted by the powers of (mu, f, b1).

    ``Z1 = b1 + f mu^2``, ``Z3_UV = -61/315 b1 + ((-3/5 + 2/105 b1) f + (-16/35 - 1/3 b1) f^2) mu^2
    + (-46/105 f^2 - 1/3 f^3) mu^4``.
    """
    return _tables()['uv'].copy()
